      تابع للهيئة الدولية لتعليم اللغة الصينية (هانبان) · وزارة التعليم الصينية<br />
      <span style={{ fontSize: "11px", opacity: 0.4 }}>© 2025 — جميع الحقوق محفوظة</span>
    </footer>
  );
}
